import {AudioEngine} from './engine.js';
import {createDeckScratchReporter} from './deck-scratch-report.js';
const $=s=>document.querySelector(s),assert=(v,m)=>{if(!v)throw Error(m);},deferred=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return{resolve,reject,promise};};
const rms=a=>Math.sqrt(a.reduce((n,v)=>n+v*v,0)/Math.max(1,a.length)),peak=a=>a.reduce((n,v)=>Math.max(n,Math.abs(v)),0);
const bounded=(p,label,ms=10000)=>{let timer;return Promise.race([p,new Promise((_,reject)=>timer=setTimeout(()=>reject(Error(label+' timed out')),ms))]).finally(()=>clearTimeout(timer));};
let reporter;
$('#run').onclick=async()=>{
 $('#run').disabled=true;reporter?.dispose();const report={status:'running',scope:'Actual production AudioEngine ordinary-scratch methods, worklet and existing routing. Silent physical sink; no UI, hardware, native or listening-quality acceptance.',checks:[],captures:[],cleanupErrors:[]};
 reporter=createDeckScratchReporter({report,results:$('#results'),status:$('#status'),download:$('#full-report')});const e=new AudioEngine(),jobs=new Map();let capture,sink,serial=0,deck;report.preparations=0;report.sourceLoadRequests=0;report.sourceLoadAcknowledgements=0;report.endCallbacks=0;const actualPrepare=e.prepareOrdinaryScratch.bind(e);e.prepareOrdinaryScratch=async d=>{report.preparations++;const transport=await actualPrepare(d),replace=transport.replaceBuffers;transport.replaceBuffers=async(...args)=>{report.sourceLoadRequests++;const value=await replace(...args);report.sourceLoadAcknowledgements++;return value;};return transport;};e.onEnd=()=>{report.endCallbacks++;};
 const update=()=>reporter.update({checkpoint:true});
 async function check(name,run){try{const evidence=await bounded(run(),name);report.checks.push({name,passed:true,evidence});}catch(error){report.checks.push({name,passed:false,error:error.message,stack:error.stack});}update();}
 try{
  report.sourceHashes={};for(const file of ['engine.js','deck-scratch.js','deck-scratch-cache.js','deck-scratch-worklet.js','deck-scratch-kernel.js','deck-scratch-engine-harness.js']){const bytes=await(await fetch(new URL(file,import.meta.url))).arrayBuffer();report.sourceHashes[file]=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');}
  e.init();e.master.gain.value=0;await e.resume();const ctx=e.ctx;report.sampleRate=ctx.sampleRate;
  await ctx.audioWorklet.addModule(new URL('./deck-scratch-capture-worklet.js',import.meta.url));
  capture=new AudioWorkletNode(ctx,'open-play-deck-scratch-capture-test',{numberOfInputs:7,numberOfOutputs:1,outputChannelCount:[2]});sink=ctx.createGain();sink.gain.value=0;capture.connect(sink);sink.connect(ctx.destination);e.nodes[0].input.channelCount=2;e.nodes[0].input.channelCountMode='explicit';e.nodes[0].input.connect(capture,0,0);
  const busKeepalive=ctx.createConstantSource();busKeepalive.offset.value=0;busKeepalive.connect(e.nodes[0].input);busKeepalive.start();
  capture.port.onmessage=({data})=>{const job=jobs.get(data.id);if(!job)return;if(data.type==='preflight')job.resolve(data);else if(data.type==='started')job.start.resolve(data);else if(data.type==='done')job.done.resolve(data);else if(data.type==='error')job.done?.reject(Error(data.error));};
  const original=ctx.createBuffer(2,22050*8,22050);for(let c=0;c<2;c++)original.getChannelData(c).fill(.2);
  const track={id:'scratch-engine-original',duration:8,bpm:120};e.buffers.set(track.id,original);
  deck={index:0,track,position:1,anchorPosition:1,anchorTime:0,rate:1,reverse:false,playing:false,slip:false,loop:false,loopIn:0,loopOut:4,keylock:false,keyShift:0,stems:[true,true,true,true],stemFX:[false,false,false,false]};
  async function record(label,seconds,action=async()=>{}){
   const warmId=++serial,warm=deferred();jobs.set(warmId,warm);capture.port.postMessage({type:'preflight',id:warmId});const preflight=await bounded(warm.promise,'capture preflight');jobs.delete(warmId);
   const id=++serial,job={start:deferred(),done:deferred()};jobs.set(id,job);capture.port.postMessage({type:'capture',id,frames:Math.ceil(seconds*ctx.sampleRate)});await bounded(job.start.promise,'capture arm');const actionResult=await action();const data=await bounded(job.done.promise,'finite capture');jobs.delete(id);
   const gaps=[];for(let i=1;i<data.rows.length;i++)if(data.rows[i].frame!==data.rows[i-1].frame+data.rows[i-1].size)gaps.push({index:i,previous:data.rows[i-1],next:data.rows[i]});
   const preflightGaps=[];for(let i=1;i<preflight.rows.length;i++)if(preflight.rows[i].frame!==preflight.rows[i-1].frame+preflight.rows[i-1].size)preflightGaps.push({index:i,previous:preflight.rows[i-1],next:preflight.rows[i]});
   const planar=new Uint8Array(data.frames*2*4);for(let c=0;c<2;c++)planar.set(new Uint8Array(data.inputs[0][c].buffer),c*data.frames*4);let binary='';for(let start=0;start<planar.length;start+=8192)binary+=String.fromCharCode(...planar.subarray(start,start+8192));
   const evidence={label,rawPCM:{format:'Planar little-endian Float32, two actual routed engine bus channels',base64:btoa(binary),sha256:Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',planar)),b=>b.toString(16).padStart(2,'0')).join('')},preflight:{rows:preflight.rows,gaps:preflightGaps,contiguous:!preflightGaps.length},armed:{rows:data.rows,gaps,contiguous:!gaps.length},armedRows:data.rows,startFrame:data.startFrame,frames:data.frames,armedGaps:gaps,rms:rms(data.inputs[0][0]),peak:peak(data.inputs[0][0]),actionResult};report.captures.push(evidence);assert(!preflightGaps.length,'Preflight calls were not contiguous');assert(!gaps.length,'Armed capture discontinuity');assert(data.rows.every(r=>r.inputChannels[0]===2),'Routed engine bus missing');return{data,evidence};
  }
  await e.preloadDeckScratch(deck);
  await check('Paused deck auditions real routed PCM, then watchdog silences a stalled move',async()=>{
   assert(await e.beginDeckScratch(deck,'engine:paused'),'Begin was refused');const r=await record('paused-motion-watchdog',.3,async()=>{await e.updateDeckScratch(deck,{position:1,velocity:1},'engine:paused');return e.voices.get(0).deckScratchTransport.state();});
   const ack=r.evidence.actionResult,offset=t=>Math.max(0,Math.floor((t-r.data.startFrame/ctx.sampleRate)*ctx.sampleRate)),moving=r.data.inputs[0][0].slice(offset(ack.audioTime+.01),offset(ack.audioTime+.07)),held=r.data.inputs[0][0].slice(offset(ack.audioTime+.16));
   const movingRMS=rms(moving),heldPeak=peak(held);assert(moving.length>100&&movingRMS>.19,'Paused motion did not reach the actual engine bus');assert(held.length>100&&heldPeak===0,'Watchdog failed to silence routed PCM');const released=await e.endDeckScratch(deck,'engine:paused');assert(!deck.playing&&!e.voices.get(0).deckScratchTransport.state().audition,'Paused release resumed');return{capture:r.evidence,movingRMS,heldPeak,released};
  });
  await check('Playing whole-deck scratch release resumes exact original bus without doubled level',async()=>{
   e.pause(deck);deck.position=1;await e.start(deck);const before=await record('ordinary-playing',.04);assert(before.evidence.rms>.199&&before.evidence.rms<.201,'Original playback fixture not audible');await e.beginDeckScratch(deck,'engine:playing');await e.updateDeckScratch(deck,{position:2,velocity:0},'engine:playing');const held=await record('ordinary-held',.04);assert(held.evidence.peak===0,'Touch hold not silent');const released=await e.endDeckScratch(deck,'engine:playing'),after=await record('ordinary-released',.04);assert(deck.playing&&after.evidence.rms>.199&&after.evidence.rms<.201,'Release failed or doubled the engine bus');return{before:before.evidence,held:held.evidence,released,after:after.evidence};
  });
  await check('Prepared stems keep original/full/subset selection through the existing real histories and gains',async()=>{
   const stems=[.01,.02,.03,.04].map(value=>{const b=ctx.createBuffer(2,ctx.sampleRate*8,ctx.sampleRate);for(let c=0;c<2;c++)b.getChannelData(c).fill(value);return b;});e.pause(deck);e.stemBuffers.set(track.id,stems);deck.position=1;await e.start(deck);await e.beginDeckScratch(deck,'engine:stems');await e.endDeckScratch(deck,'engine:stems');const all=await record('all-stems-original-selected',.04);assert(Math.abs(all.evidence.rms-.2)<.001,'All-on doubled original and stems');deck.stems=[true,false,true,false];e.updateStems(deck);const subset=await record('stem-subset-selected',.04);assert(Math.abs(subset.evidence.rms-.04)<.001,'Subset did not traverse actual existing stem history/gains');deck.stems=[false,false,false,false];e.updateStems(deck);const muted=await record('all-stems-muted',.04);assert(muted.evidence.peak<1e-8,'Muted stems leaked');return{all:all.evidence,subset:subset.evidence,muted:muted.evidence};
  });
  await check('Pause retires active audible routed scratch and stale owner cannot revive it',async()=>{
   deck.stems=[true,true,true,true];e.updateStems(deck);const before=await record('before-pause',.04);assert(before.evidence.rms>.19,'Disposal prerequisite not audible');await e.beginDeckScratch(deck,'engine:retire');await e.updateDeckScratch(deck,{position:2,velocity:1},'engine:retire');e.pause(deck);assert(await e.updateDeckScratch(deck,{position:3,velocity:1},'engine:retire')===false,'Retired owner accepted');const after=await record('after-pause',.04);assert(after.evidence.peak===0&&!deck.playing&&!e.voices.has(0),'Pause leaked or revived audio');return{before:before.evidence,after:after.evidence};
  });
  await check('Pause and rebegin reuse acknowledged PCM; explicit clear terminally releases the cached owner',async()=>{
   const cache=e.scratchCache.peek(0),transport=cache?.transport,counts={preparations:report.preparations,loads:report.sourceLoadAcknowledgements};assert(transport&&transport.state().sourceCount===5,'Prepared five-source cache absent');
   assert(!transport.state().playing&&!transport.state().audition&&!transport.state().owner,'Cached pause retained an active owner');await e.beginDeckScratch(deck,'engine:cached');await e.updateDeckScratch(deck,{position:2,velocity:0},'engine:cached');await e.endDeckScratch(deck,'engine:cached');e.pause(deck);
   assert(e.scratchCache.peek(0).transport===transport&&report.preparations===counts.preparations&&report.sourceLoadAcknowledgements===counts.loads,'Same-source gesture copied/recreated PCM');const quiet=await record('cached-pause-silent',.04);assert(quiet.evidence.peak===0,'Cached paused source leaked');e.clearDeckScratchCache(0);assert(!e.scratchCache.peek(0)&&transport.state().disposed&&transport.state().sourceCount===0,'Explicit clear did not terminally release PCM');return{counts,quiet:quiet.evidence,terminal:transport.state()};
  });
  await check('Paused touch at original duration preserves the warm source and never invokes end/autoplay',async()=>{
   deck.position=track.duration;const before=report.endCallbacks;await e.preloadDeckScratch(deck);await e.beginDeckScratch(deck,'engine:paused-end');await e.updateDeckScratch(deck,{position:track.duration,velocity:0},'engine:paused-end');await e.endDeckScratch(deck,'engine:paused-end');const quiet=await record('paused-at-end',.04);assert(!deck.playing&&report.endCallbacks===before,'Paused edge falsely invoked natural end');assert(e.scratchCache.peek(0)?.transport.state().sourceCount===5,'Paused edge discarded prepared PCM');return{quiet:quiet.evidence,endCallbacks:report.endCallbacks};
  });
  await check('Natural playing end fires once and leaves its cached PCM silent without orphan ownership',async()=>{
   e.pause(deck);deck.position=7.7;const before=report.endCallbacks;await e.start(deck);await e.beginDeckScratch(deck,'engine:natural-end');await e.endDeckScratch(deck,'engine:natural-end');const ended=await record('natural-end',.45);assert(report.endCallbacks===before+1&&!deck.playing&&!e.voices.has(0),'Natural end did not settle exactly once');const cache=e.scratchCache.peek(0);assert(cache&&!cache.transport.state().playing&&!cache.transport.state().audition&&!cache.transport.state().owner,'Ended cache retains playback/gesture');const tail=ended.data.inputs[0][0].slice(-Math.floor(.08*ctx.sampleRate));assert(peak(tail)===0,'Natural end PCM tail not silent');return{capture:ended.evidence,endCallbacks:report.endCallbacks,cached:cache.transport.state()};
  });
 }catch(error){report.checks.push({name:'Setup/unhandled failure',passed:false,error:error.message,stack:error.stack});}
 finally{if(deck)e.pause(deck);e.scratchCache.clearAll();try{capture?.port.postMessage({type:'stop'});capture?.disconnect();capture?.port.close();sink?.disconnect();await bounded(e.ctx?.close(),'context close',2000);}catch(error){report.cleanupErrors.push(error.message);}report.status=report.checks.every(c=>c.passed)&&!report.cleanupErrors.length?'finished':'failed';update();$('#run').disabled=false;}
};
